        yield* emit(
          events,
          command,
        )({
          type: "thread.unsnoozed",
          threadId: command.threadId,
          providerInstanceId: projection.thread.providerInstanceId,
          occurredAt: now,
          payload: { ...projection.thread, snoozedUntil: null, snoozedAt: null, updatedAt: now },
        });
