      // notification: it starts a turn, or follows the one running. Only the
      // answer that closes the card wakes it, and never a closed thread.
      if (
        wake === undefined ||
        unchanged ||
        projection.thread.archivedAt !== null ||
        projection.thread.deletedAt !== null
