          occurredAt: now,
          payload: {
            id: idAllocator.derive.userTurnItem({ messageId }),
            threadId: command.threadId,
            runId: requestNode?.runId ?? null,
            nodeId: runtimeRequest.nodeId,
            providerThreadId:
