      if (steerableRun === undefined) {
        return yield* new ThreadManagementNoSteerableRunError({
          threadId: input.threadId,
          mode,
        });
      }
      dispatchMode = {
        type: mode === "steer" ? "steer_active" : "restart_active",
        targetRunId: steerableRun.id,
      };
